{"cases": [{"case_id": "sha256:12b7db593ae1805089b04dcd9fcc68e9b9f2f8a85fa122dd51a19af43fcda0bb", "record": {"task_id": "ifeval-2853", "family": "ifeval-source-2853", "sample_id": "sha256:11ab15c79e9e39f9c0fbc50aae132d76b72457d0aeb6097395b536e5379c4d5d", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Write a poem about flooding in Donnell, TX. The poem should have a title in double angular brackets, i.e. <<title>>, and contains at least 3 words in all capital letters.", "feedback": "{\"response\": \"<<Donnell Underwater>>\\n\\nRain drums hard on Donnell\\u2019s tin roofs,  \\nCreeks rise like dark, restless hands;  \\nThe roads become RIVERS,  \\nThe fields turn MIRRORS,  \\nAnd water swallows the sand.\\n\\nPorches hold lanterns against the night,  \\nNeighbors call from house to house;  \\nA child whispers, \\u201cHOME,\\u201d  \\nAs the floodwaters roam  \\nLike thunder beneath a house.\\n\\nBy dawn, the clouds break open,  \\nAnd mud clings to every door;  \\nYet HOPE lights the sky,  \\nAs the waters sink by\\u2014  \\nDonnell will rise once more.\", \"checks\": {\"0:change_case:capital_word_frequency\": true, \"1:detectable_format:title\": true}}", "evidence_refs": ["seed-101/failure/round-1/diagnostic/ifeval-2853"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}, {"case_id": "sha256:1ac6e38ae809e9af20477e308fb8a1e94b620b4d2e8e4327a7fd54ca2185f8ae", "record": {"task_id": "ifeval-3407", "family": "ifeval-source-3407", "sample_id": "sha256:19fd399536b860dd60518df2c998a3a034fb7518e1c544d2f8bb8b9f0832c0c0", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": false, "co