{
  "suggestions": [
    {
      "approach": "Build shared governance",
      "actions": [
        "Invite immigrant community representatives to co-design the exhibit, select themes, and approve interpretive text.",
        "Create a paid advisory group with clear decision-making authority."
      ]
    },
    {
      "approach": "Obtain informed consent",
      "actions": [
        "Explain recording, editing, publication, translation, and future-use plans in participants’ preferred languages.",
        "Allow contributors to review, revise, restrict, or withdraw material before opening."
      ]
    },
    {
      "approach": "Compensate participation",
      "actions": [
        "Ensure interviewees, translators, advisors, and community partners are fairly compensated.",
        "Cover transportation, childcare, meals, and other participation costs."
      ]
    },
    {
      "approach": "Protect privacy and safety",
      "actions": [
        "Offer anonymity or pseudonyms, especially for people with uncertain legal status or sensitive experiences.",
        "Store recordings securely and define who may access them and for how long."
      ]
    },
    {
      "approach": "Represent people accurately",
      "actions": [
        "Avoid presenting immigrants as a single group or focusing only on trauma.",
        "Include everyday life, achievements, disagreements, humor, and varied generations and backgrounds."
      ]
    },
    {
      "approach": "Share ownership and benefits",
      "actions": [
        "Give contributors copies of recordings and translated transcripts.",
        "Return exhibit materials through community events, digital access, and partner organizations."
      ]
    },
    {
      "approach": "Make the exhibit accessible",
      "actions": [
        "Provide multilingual labels, captions, transcripts, plain-language summaries, and interpretation.",
        "Schedule free community previews and transportation-friendly programs."
      ]
    },
    {
      "approach": "Evaluate accountability",
      "actions": [
        "Ask participating communities to review the exhibit before launch.",
        "Publish how feedback changed the project and establish a process for correcting errors after opening."
      ]
    }
  ],
  "keywords": [
    "compensated",
    "immigrants"
  ]
}

